/**
 * Validates JSON input from stdin.
 * Exits with code 0 on valid JSON, code 1 with an error message on invalid JSON.
 */

/**
 * Validate whether a string is valid JSON.
 * Returns an object with `valid` boolean and optional `error` message.
 */
export function validateJson(input: string): { valid: boolean; error?: string } {
  if (input.trim() === "") {
    return { valid: false, error: "Empty input" };
  }

  try {
    JSON.parse(input);
    return { valid: true };
  } catch (err) {
    const message = err instanceof Error ? err.message : "Unknown error";
    return { valid: false, error: message };
  }
}

/**
 * Read all of stdin as text using Bun APIs.
 */
async function readStdin(): Promise<string> {
  const chunks: Uint8Array[] = [];
  const reader = Bun.stdin.stream().getReader();

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    if (value) chunks.push(value);
  }

  return new TextDecoder().decode(Buffer.concat(chunks));
}

async function main(): Promise<void> {
  const input = await readStdin();
  const result = validateJson(input);

  if (result.valid) {
    console.log("Valid JSON");
    process.exit(0);
  } else {
    console.error(`Invalid JSON: ${result.error}`);
    process.exit(1);
  }
}

main();

import { describe, expect, test } from "bun:test";
import { validateJson } from "./validate-json";

describe("validateJson", () => {
  test("returns valid for a JSON object", () => {
    const result = validateJson('{"key": "value"}');
    expect(result.valid).toBe(true);
    expect(result.error).toBeUndefined();
  });

  test("returns valid for a JSON array", () => {
    const result = validateJson('[1, 2, 3]');
    expect(result.valid).toBe(true);
  });

  test("returns valid for a JSON primitive string", () => {
    const result = validateJson('"hello"');
    expect(result.valid).toBe(true);
  });

  test("returns invalid with error for malformed JSON", () => {
    const result = validateJson("{bad json}");
    expect(result.valid).toBe(false);
    expect(result.error).toBeDefined();
  });

  test("returns invalid with error for empty input", () => {
    const result = validateJson("");
    expect(result.valid).toBe(false);
    expect(result.error).toBe("Empty input");
  });

  test("returns invalid with error for whitespace-only input", () => {
    const result = validateJson("   \n  ");
    expect(result.valid).toBe(false);
    expect(result.error).toBe("Empty input");
  });
});

