/**
 * High-performance JSON validation module.
 *
 * Provides syntax validation via single-pass character scanning (no JSON.parse
 * allocation overhead) and structural schema validation for parsed values.
 */

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type JsonSchemaType =
  | "string"
  | "number"
  | "boolean"
  | "null"
  | "array"
  | "object";

export interface JsonSchema {
  type: JsonSchemaType | JsonSchemaType[];
  properties?: Record<string, JsonSchema>;
  items?: JsonSchema;
  required?: string[];
}

export interface ValidationError {
  path: string;
  message: string;
}

export interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
}

// ---------------------------------------------------------------------------
// isValidJson  (T1 - single-pass character scanner)
// ---------------------------------------------------------------------------

/**
 * Validate whether `input` is syntactically valid JSON using a single-pass
 * character scanner with early bailout.  No object graph is allocated.
 */
export function isValidJson(input: string): boolean {
  const len = input.length;
  if (len === 0) return false;

  let pos = 0;

  // -- helpers --------------------------------------------------------------

  function skipWhitespace(): void {
    while (pos < len) {
      const ch = input.charCodeAt(pos);
      if (ch === 0x20 || ch === 0x09 || ch === 0x0a || ch === 0x0d) {
        pos++;
      } else {
        break;
      }
    }
  }

  function parseValue(): boolean {
    skipWhitespace();
    if (pos >= len) return false;

    const ch = input.charCodeAt(pos);

    switch (ch) {
      case 0x22: // "
        return parseString();
      case 0x7b: // {
        return parseObject();
      case 0x5b: // [
        return parseArray();
      case 0x74: // t (true)
        return parseLiteral("true");
      case 0x66: // f (false)
        return parseLiteral("false");
      case 0x6e: // n (null)
        return parseLiteral("null");
      default:
        return parseNumber();
    }
  }

  function parseLiteral(expected: string): boolean {
    for (let i = 0; i < expected.length; i++) {
      if (pos >= len || input[pos] !== expected[i]) return false;
      pos++;
    }
    return true;
  }

  function parseString(): boolean {
    if (pos >= len || input.charCodeAt(pos) !== 0x22) return false;
    pos++; // skip opening quote

    while (pos < len) {
      const ch = input.charCodeAt(pos);

      if (ch === 0x22) {
        // closing quote
        pos++;
        return true;
      }

      if (ch === 0x5c) {
        // backslash
        pos++;
        if (pos >= len) return false;
        const esc = input[pos];
        if (
          esc === '"' ||
          esc === "\\" ||
          esc === "/" ||
          esc === "b" ||
          esc === "f" ||
          esc === "n" ||
          esc === "r" ||
          esc === "t"
        ) {
          pos++;
        } else if (esc === "u") {
          pos++;
          for (let i = 0; i < 4; i++) {
            if (pos >= len || !isHexDigit(input.charCodeAt(pos))) return false;
            pos++;
          }
        } else {
          return false;
        }
      } else if (ch < 0x20) {
        // control characters are invalid unescaped
        return false;
      } else {
        pos++;
      }
    }

    return false; // unterminated string
  }

  function isHexDigit(code: number): boolean {
    return (
      (code >= 0x30 && code <= 0x39) || // 0-9
      (code >= 0x41 && code <= 0x46) || // A-F
      (code >= 0x61 && code <= 0x66) // a-f
    );
  }

  function parseNumber(): boolean {
    const start = pos;

    // optional minus
    if (pos < len && input.charCodeAt(pos) === 0x2d) pos++;

    // integer part
    if (pos >= len) return false;
    if (input.charCodeAt(pos) === 0x30) {
      // leading zero: must be just '0'
      pos++;
    } else if (input.charCodeAt(pos) >= 0x31 && input.charCodeAt(pos) <= 0x39) {
      pos++;
      while (pos < len && input.charCodeAt(pos) >= 0x30 && input.charCodeAt(pos) <= 0x39) {
        pos++;
      }
    } else {
      return false;
    }

    // fractional part
    if (pos < len && input.charCodeAt(pos) === 0x2e) {
      pos++;
      if (pos >= len || input.charCodeAt(pos) < 0x30 || input.charCodeAt(pos) > 0x39) {
        return false;
      }
      while (pos < len && input.charCodeAt(pos) >= 0x30 && input.charCodeAt(pos) <= 0x39) {
        pos++;
      }
    }

    // exponent part
    if (pos < len && (input.charCodeAt(pos) === 0x45 || input.charCodeAt(pos) === 0x65)) {
      pos++;
      if (pos < len && (input.charCodeAt(pos) === 0x2b || input.charCodeAt(pos) === 0x2d)) {
        pos++;
      }
      if (pos >= len || input.charCodeAt(pos) < 0x30 || input.charCodeAt(pos) > 0x39) {
        return false;
      }
      while (pos < len && input.charCodeAt(pos) >= 0x30 && input.charCodeAt(pos) <= 0x39) {
        pos++;
      }
    }

    return pos > start;
  }

  function parseArray(): boolean {
    pos++; // skip [
    skipWhitespace();

    if (pos < len && input.charCodeAt(pos) === 0x5d) {
      pos++;
      return true; // empty array
    }

    while (true) {
      if (!parseValue()) return false;
      skipWhitespace();
      if (pos >= len) return false;

      if (input.charCodeAt(pos) === 0x5d) {
        pos++;
        return true;
      }
      if (input.charCodeAt(pos) !== 0x2c) return false;
      pos++; // skip comma
    }
  }

  function parseObject(): boolean {
    pos++; // skip {
    skipWhitespace();

    if (pos < len && input.charCodeAt(pos) === 0x7d) {
      pos++;
      return true; // empty object
    }

    while (true) {
      skipWhitespace();
      if (!parseString()) return false;

      skipWhitespace();
      if (pos >= len || input.charCodeAt(pos) !== 0x3a) return false;
      pos++; // skip colon

      if (!parseValue()) return false;

      skipWhitespace();
      if (pos >= len) return false;

      if (input.charCodeAt(pos) === 0x7d) {
        pos++;
        return true;
      }
      if (input.charCodeAt(pos) !== 0x2c) return false;
      pos++; // skip comma
    }
  }

  // -- main parse -----------------------------------------------------------

  const result = parseValue();
  if (!result) return false;

  // ensure no trailing non-whitespace
  skipWhitespace();
  return pos === len;
}

// ---------------------------------------------------------------------------
// validateJsonSchema  (T2 - structural schema validation)
// ---------------------------------------------------------------------------

/**
 * Validate a parsed JSON value against a simple type-descriptor schema.
 * Returns a `ValidationResult` with typed errors indicating mismatches.
 */
export function validateJsonSchema(
  data: unknown,
  schema: JsonSchema,
): ValidationResult {
  const errors: ValidationError[] = [];
  validate(data, schema, "");
  return { valid: errors.length === 0, errors };

  function actualType(value: unknown): JsonSchemaType {
    if (value === null) return "null";
    if (Array.isArray(value)) return "array";
    return typeof value as JsonSchemaType;
  }

  function typeMatches(value: unknown, expected: JsonSchemaType | JsonSchemaType[]): boolean {
    const actual = actualType(value);
    if (Array.isArray(expected)) {
      return expected.includes(actual);
    }
    return actual === expected;
  }

  function validate(value: unknown, s: JsonSchema, path: string): void {
    // Type check
    if (!typeMatches(value, s.type)) {
      const expected = Array.isArray(s.type) ? s.type.join(" | ") : s.type;
      errors.push({
        path: path || "$",
        message: `Expected type ${expected} but got ${actualType(value)}`,
      });
      return;
    }

    // Object property validation
    if (
      actualType(value) === "object" &&
      value !== null &&
      !Array.isArray(value)
    ) {
      const obj = value as Record<string, unknown>;

      // Check required fields
      if (s.required) {
        for (const key of s.required) {
          if (!(key in obj)) {
            errors.push({
              path: path ? `${path}.${key}` : key,
              message: `Missing required property "${key}"`,
            });
          }
        }
      }

      // Validate known properties
      if (s.properties) {
        for (const [key, propSchema] of Object.entries(s.properties)) {
          if (key in obj) {
            validate(obj[key], propSchema, path ? `${path}.${key}` : key);
          }
        }
      }
    }

    // Array item validation
    if (Array.isArray(value) && s.items) {
      for (let i = 0; i < value.length; i++) {
        validate(value[i], s.items, `${path}[${i}]`);
      }
    }
  }
}

// ---------------------------------------------------------------------------
// CLI entry point
// ---------------------------------------------------------------------------

if (import.meta.main) {
  const input = process.argv[2];
  if (!input) {
    console.log("Usage: bun run src/json-validator.ts '<json-string>'");
    process.exit(1);
  }
  const valid = isValidJson(input);
  console.log(valid ? "Valid JSON" : "Invalid JSON");
  process.exit(valid ? 0 : 1);
}

import { describe, expect, test } from "bun:test";
import {
  isValidJson,
  validateJsonSchema,
  type JsonSchema,
} from "./json-validator";

// ---------------------------------------------------------------------------
// isValidJson
// ---------------------------------------------------------------------------

describe("isValidJson", () => {
  describe("valid JSON values", () => {
    test("simple object", () => {
      expect(isValidJson('{"a":1}')).toBe(true);
    });

    test("nested object", () => {
      expect(isValidJson('{"a":{"b":{"c":true}}}')).toBe(true);
    });

    test("simple array", () => {
      expect(isValidJson("[1,2,3]")).toBe(true);
    });

    test("array of objects", () => {
      expect(isValidJson('[{"id":1},{"id":2}]')).toBe(true);
    });

    test("string value", () => {
      expect(isValidJson('"hello"')).toBe(true);
    });

    test("number integer", () => {
      expect(isValidJson("42")).toBe(true);
    });

    test("number negative", () => {
      expect(isValidJson("-7")).toBe(true);
    });

    test("number with decimal", () => {
      expect(isValidJson("3.14")).toBe(true);
    });

    test("number with exponent", () => {
      expect(isValidJson("1e10")).toBe(true);
    });

    test("number with negative exponent", () => {
      expect(isValidJson("2.5e-3")).toBe(true);
    });

    test("number with positive exponent sign", () => {
      expect(isValidJson("1E+2")).toBe(true);
    });

    test("boolean true", () => {
      expect(isValidJson("true")).toBe(true);
    });

    test("boolean false", () => {
      expect(isValidJson("false")).toBe(true);
    });

    test("null", () => {
      expect(isValidJson("null")).toBe(true);
    });

    test("empty object", () => {
      expect(isValidJson("{}")).toBe(true);
    });

    test("empty array", () => {
      expect(isValidJson("[]")).toBe(true);
    });

    test("whitespace around value", () => {
      expect(isValidJson('  { "key" : "value" }  ')).toBe(true);
    });

    test("string with escape sequences", () => {
      expect(isValidJson('"line1\\nline2\\ttab"')).toBe(true);
    });

    test("string with unicode escape", () => {
      expect(isValidJson('"\\u0041\\u0042"')).toBe(true);
    });

    test("string with escaped quote", () => {
      expect(isValidJson('"say \\"hello\\""')).toBe(true);
    });

    test("string with escaped backslash", () => {
      expect(isValidJson('"path\\\\to\\\\file"')).toBe(true);
    });

    test("string with solidus escape", () => {
      expect(isValidJson('"a\\/b"')).toBe(true);
    });

    test("zero", () => {
      expect(isValidJson("0")).toBe(true);
    });

    test("negative zero", () => {
      expect(isValidJson("-0")).toBe(true);
    });

    test("deeply nested arrays", () => {
      expect(isValidJson("[[[[[]]]]]")).toBe(true);
    });

    test("mixed types in array", () => {
      expect(isValidJson('[1,"two",true,null,{},[]]')).toBe(true);
    });
  });

  describe("invalid JSON", () => {
    test("empty string", () => {
      expect(isValidJson("")).toBe(false);
    });

    test("bare word", () => {
      expect(isValidJson("undefined")).toBe(false);
    });

    test("single quote string", () => {
      expect(isValidJson("'hello'")).toBe(false);
    });

    test("trailing comma in object", () => {
      expect(isValidJson('{"a":1,}')).toBe(false);
    });

    test("trailing comma in array", () => {
      expect(isValidJson("[1,2,]")).toBe(false);
    });

    test("missing value in object", () => {
      expect(isValidJson('{"a":}')).toBe(false);
    });

    test("unquoted key", () => {
      expect(isValidJson("{a:1}")).toBe(false);
    });

    test("unterminated string", () => {
      expect(isValidJson('"hello')).toBe(false);
    });

    test("unterminated object", () => {
      expect(isValidJson('{"a":1')).toBe(false);
    });

    test("unterminated array", () => {
      expect(isValidJson("[1,2")).toBe(false);
    });

    test("leading zeros in number", () => {
      expect(isValidJson("01")).toBe(false);
    });

    test("plus prefix on number", () => {
      expect(isValidJson("+1")).toBe(false);
    });

    test("trailing content", () => {
      expect(isValidJson("true false")).toBe(false);
    });

    test("invalid escape sequence", () => {
      expect(isValidJson('"\\x41"')).toBe(false);
    });

    test("incomplete unicode escape", () => {
      expect(isValidJson('"\\u00"')).toBe(false);
    });

    test("invalid unicode hex digits", () => {
      expect(isValidJson('"\\uGGGG"')).toBe(false);
    });

    test("raw control character in string", () => {
      expect(isValidJson('"\t"')).toBe(false);
    });

    test("decimal point without trailing digit", () => {
      expect(isValidJson("1.")).toBe(false);
    });

    test("exponent without digit", () => {
      expect(isValidJson("1e")).toBe(false);
    });

    test("minus without digit", () => {
      expect(isValidJson("-")).toBe(false);
    });

    test("just whitespace", () => {
      expect(isValidJson("   ")).toBe(false);
    });

    test("NaN is not valid JSON", () => {
      expect(isValidJson("NaN")).toBe(false);
    });

    test("Infinity is not valid JSON", () => {
      expect(isValidJson("Infinity")).toBe(false);
    });
  });
});

// ---------------------------------------------------------------------------
// validateJsonSchema
// ---------------------------------------------------------------------------

describe("validateJsonSchema", () => {
  describe("type validation", () => {
    test("accepts matching string type", () => {
      const result = validateJsonSchema("hello", { type: "string" });
      expect(result.valid).toBe(true);
      expect(result.errors).toHaveLength(0);
    });

    test("accepts matching number type", () => {
      const result = validateJsonSchema(42, { type: "number" });
      expect(result.valid).toBe(true);
    });

    test("accepts matching boolean type", () => {
      const result = validateJsonSchema(true, { type: "boolean" });
      expect(result.valid).toBe(true);
    });

    test("accepts null type", () => {
      const result = validateJsonSchema(null, { type: "null" });
      expect(result.valid).toBe(true);
    });

    test("accepts array type", () => {
      const result = validateJsonSchema([1, 2], { type: "array" });
      expect(result.valid).toBe(true);
    });

    test("accepts object type", () => {
      const result = validateJsonSchema({ a: 1 }, { type: "object" });
      expect(result.valid).toBe(true);
    });

    test("rejects type mismatch", () => {
      const result = validateJsonSchema("hello", { type: "number" });
      expect(result.valid).toBe(false);
      expect(result.errors).toHaveLength(1);
      expect(result.errors[0].path).toBe("$");
      expect(result.errors[0].message).toContain("Expected type number");
      expect(result.errors[0].message).toContain("got string");
    });

    test("accepts union type", () => {
      const schema: JsonSchema = { type: ["string", "null"] };
      expect(validateJsonSchema("hi", schema).valid).toBe(true);
      expect(validateJsonSchema(null, schema).valid).toBe(true);
    });

    test("rejects value not in union type", () => {
      const schema: JsonSchema = { type: ["string", "null"] };
      const result = validateJsonSchema(42, schema);
      expect(result.valid).toBe(false);
      expect(result.errors[0].message).toContain("string | null");
    });
  });

  describe("object property validation", () => {
    const schema: JsonSchema = {
      type: "object",
      required: ["name", "age"],
      properties: {
        name: { type: "string" },
        age: { type: "number" },
        active: { type: "boolean" },
      },
    };

    test("accepts valid object", () => {
      const result = validateJsonSchema(
        { name: "Alice", age: 30, active: true },
        schema,
      );
      expect(result.valid).toBe(true);
    });

    test("reports missing required property", () => {
      const result = validateJsonSchema({ name: "Alice" }, schema);
      expect(result.valid).toBe(false);
      expect(result.errors).toHaveLength(1);
      expect(result.errors[0].path).toBe("age");
      expect(result.errors[0].message).toContain('Missing required property "age"');
    });

    test("reports wrong property type", () => {
      const result = validateJsonSchema(
        { name: "Alice", age: "thirty" },
        schema,
      );
      expect(result.valid).toBe(false);
      expect(result.errors.some((e) => e.path === "age")).toBe(true);
    });

    test("allows extra properties not in schema", () => {
      const result = validateJsonSchema(
        { name: "Alice", age: 30, extra: "ok" },
        schema,
      );
      expect(result.valid).toBe(true);
    });
  });

  describe("array items validation", () => {
    const schema: JsonSchema = {
      type: "array",
      items: { type: "number" },
    };

    test("accepts valid array items", () => {
      const result = validateJsonSchema([1, 2, 3], schema);
      expect(result.valid).toBe(true);
    });

    test("rejects invalid array item", () => {
      const result = validateJsonSchema([1, "two", 3], schema);
      expect(result.valid).toBe(false);
      expect(result.errors).toHaveLength(1);
      expect(result.errors[0].path).toBe("[1]");
    });

    test("accepts empty array", () => {
      const result = validateJsonSchema([], schema);
      expect(result.valid).toBe(true);
    });
  });

  describe("nested schema validation", () => {
    const schema: JsonSchema = {
      type: "object",
      required: ["user"],
      properties: {
        user: {
          type: "object",
          required: ["name"],
          properties: {
            name: { type: "string" },
            tags: {
              type: "array",
              items: { type: "string" },
            },
          },
        },
      },
    };

    test("accepts valid nested structure", () => {
      const result = validateJsonSchema(
        { user: { name: "Alice", tags: ["admin", "user"] } },
        schema,
      );
      expect(result.valid).toBe(true);
    });

    test("reports nested type error with correct path", () => {
      const result = validateJsonSchema(
        { user: { name: 123 } },
        schema,
      );
      expect(result.valid).toBe(false);
      expect(result.errors[0].path).toBe("user.name");
    });

    test("reports nested array item error with correct path", () => {
      const result = validateJsonSchema(
        { user: { name: "Alice", tags: ["ok", 42] } },
        schema,
      );
      expect(result.valid).toBe(false);
      expect(result.errors[0].path).toBe("user.tags[1]");
    });
  });
});

